import Database from 'better-sqlite3';
import path from 'path';
import fs from 'fs';

const DB_DIR = path.join(process.cwd(), 'data');
const DB_PATH = path.join(DB_DIR, 'coach.db');

if (!fs.existsSync(DB_DIR)) {
  fs.mkdirSync(DB_DIR, { recursive: true });
}

let db: Database.Database;

function getDb(): Database.Database {
  if (!db) {
    db = new Database(DB_PATH);
    db.pragma('journal_mode = WAL');
    db.pragma('foreign_keys = ON');
    initSchema(db);
  }
  return db;
}

function initSchema(database: Database.Database) {
  database.exec(`
    CREATE TABLE IF NOT EXISTS plays (
      id TEXT PRIMARY KEY,
      created_at TEXT DEFAULT (datetime('now')),
      defensive_formation TEXT,
      play_name TEXT,
      play_type TEXT,
      full_play_call TEXT,
      defensive_analysis TEXT,
      offensive_counter TEXT,
      whiteboard_data TEXT,
      media_data TEXT,
      media_type TEXT,
      chat_history TEXT,
      situation_tags TEXT DEFAULT '[]',
      personnel TEXT DEFAULT '11',
      field_zone TEXT DEFAULT '',
      formation TEXT DEFAULT '',
      opponent_id TEXT DEFAULT '',
      week_id TEXT DEFAULT '',
      confidence_rank INTEGER DEFAULT 3
    );

    CREATE TABLE IF NOT EXISTS terminology (
      id TEXT PRIMARY KEY,
      standard_term TEXT NOT NULL,
      custom_term TEXT NOT NULL,
      category TEXT NOT NULL,
      created_at TEXT DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS opponents (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      abbreviation TEXT DEFAULT '',
      notes TEXT DEFAULT '',
      created_at TEXT DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS schedule (
      id TEXT PRIMARY KEY,
      season_year INTEGER NOT NULL,
      week_number INTEGER NOT NULL,
      opponent_id TEXT,
      game_date TEXT DEFAULT '',
      status TEXT DEFAULT 'upcoming',
      notes TEXT DEFAULT '',
      created_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (opponent_id) REFERENCES opponents(id) ON DELETE SET NULL
    );

    CREATE TABLE IF NOT EXISTS game_plans (
      id TEXT PRIMARY KEY,
      week_id TEXT NOT NULL,
      status TEXT DEFAULT 'draft',
      opening_script TEXT DEFAULT '[]',
      call_sheet_data TEXT DEFAULT '{}',
      tendency_notes TEXT DEFAULT '',
      notes TEXT DEFAULT '',
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (week_id) REFERENCES schedule(id) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS tendency_reports (
      id TEXT PRIMARY KEY,
      opponent_id TEXT NOT NULL,
      report_data TEXT DEFAULT '{}',
      film_count INTEGER DEFAULT 0,
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (opponent_id) REFERENCES opponents(id) ON DELETE CASCADE
    );
  `);

  // Add columns to plays if they don't exist (migration for existing databases)
  const columns = database.prepare("PRAGMA table_info(plays)").all() as { name: string }[];
  const colNames = columns.map(c => c.name);
  const newCols: [string, string][] = [
    ['situation_tags', "TEXT DEFAULT '[]'"],
    ['personnel', "TEXT DEFAULT '11'"],
    ['field_zone', "TEXT DEFAULT ''"],
    ['formation', "TEXT DEFAULT ''"],
    ['opponent_id', "TEXT DEFAULT ''"],
    ['week_id', "TEXT DEFAULT ''"],
    ['confidence_rank', "INTEGER DEFAULT 3"],
  ];
  for (const [name, def] of newCols) {
    if (!colNames.includes(name)) {
      database.prepare(`ALTER TABLE plays ADD COLUMN ${name} ${def}`).run();
    }
  }
}

// ═══════════════════════════════════════════════════════
// PLAY CRUD
// ═══════════════════════════════════════════════════════

export interface PlayRecord {
  id: string;
  created_at: string;
  defensive_formation: string;
  play_name: string;
  play_type: string;
  full_play_call: string;
  defensive_analysis: string;
  offensive_counter: string;
  whiteboard_data: string;
  media_data: string;
  media_type: string;
  chat_history: string;
  situation_tags: string;
  personnel: string;
  field_zone: string;
  formation: string;
  opponent_id: string;
  week_id: string;
  confidence_rank: number;
}

export function getAllPlays(filters?: {
  play_type?: string;
  search?: string;
  opponent_id?: string;
  week_id?: string;
  personnel?: string;
  situation?: string;
  field_zone?: string;
}): PlayRecord[] {
  const database = getDb();
  let query = 'SELECT * FROM plays';
  const conditions: string[] = [];
  const params: string[] = [];

  if (filters?.play_type && filters.play_type !== 'All') {
    conditions.push('play_type = ?');
    params.push(filters.play_type);
  }
  if (filters?.search) {
    conditions.push(
      '(play_name LIKE ? OR defensive_formation LIKE ? OR full_play_call LIKE ? OR formation LIKE ?)'
    );
    const term = `%${filters.search}%`;
    params.push(term, term, term, term);
  }
  if (filters?.opponent_id) {
    conditions.push('opponent_id = ?');
    params.push(filters.opponent_id);
  }
  if (filters?.week_id) {
    conditions.push('week_id = ?');
    params.push(filters.week_id);
  }
  if (filters?.personnel) {
    conditions.push('personnel = ?');
    params.push(filters.personnel);
  }
  if (filters?.situation) {
    conditions.push('situation_tags LIKE ?');
    params.push(`%${filters.situation}%`);
  }
  if (filters?.field_zone) {
    conditions.push('field_zone = ?');
    params.push(filters.field_zone);
  }

  if (conditions.length > 0) {
    query += ' WHERE ' + conditions.join(' AND ');
  }
  query += ' ORDER BY created_at DESC';

  return database.prepare(query).all(...params) as PlayRecord[];
}

export function getPlayById(id: string): PlayRecord | undefined {
  const database = getDb();
  return database.prepare('SELECT * FROM plays WHERE id = ?').get(id) as
    | PlayRecord
    | undefined;
}

export function insertPlay(play: Partial<PlayRecord> & { id: string }): void {
  const database = getDb();
  database
    .prepare(
      `INSERT INTO plays (id, defensive_formation, play_name, play_type, full_play_call,
       defensive_analysis, offensive_counter, whiteboard_data, media_data, media_type, chat_history,
       situation_tags, personnel, field_zone, formation, opponent_id, week_id, confidence_rank)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    )
    .run(
      play.id,
      play.defensive_formation || '',
      play.play_name || '',
      play.play_type || '',
      play.full_play_call || '',
      play.defensive_analysis || '{}',
      play.offensive_counter || '{}',
      play.whiteboard_data || '{}',
      play.media_data || '',
      play.media_type || '',
      play.chat_history || '[]',
      play.situation_tags || '[]',
      play.personnel || '11',
      play.field_zone || '',
      play.formation || '',
      play.opponent_id || '',
      play.week_id || '',
      play.confidence_rank ?? 3
    );
}

export function updatePlay(id: string, updates: Partial<PlayRecord>): void {
  const database = getDb();
  const fields: string[] = [];
  const values: unknown[] = [];
  for (const [key, value] of Object.entries(updates)) {
    if (key !== 'id' && key !== 'created_at') {
      fields.push(`${key} = ?`);
      values.push(value);
    }
  }
  if (fields.length === 0) return;
  values.push(id);
  database.prepare(`UPDATE plays SET ${fields.join(', ')} WHERE id = ?`).run(...values);
}

export function deletePlay(id: string): void {
  const database = getDb();
  database.prepare('DELETE FROM plays WHERE id = ?').run(id);
}

export function getPlaysByWeek(weekId: string): PlayRecord[] {
  const database = getDb();
  return database.prepare('SELECT * FROM plays WHERE week_id = ? ORDER BY confidence_rank DESC, play_name').all(weekId) as PlayRecord[];
}

