import { NextRequest, NextResponse } from 'next/server';
import { v4 as uuidv4 } from 'uuid';
import {
  getGamePlanByWeek,
  getPlaysByWeek,
  upsertGamePlan,
  updateGamePlan,
} from '@/lib/db';

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const weekId = searchParams.get('week_id');

    if (!weekId) {
      return NextResponse.json(
        { error: 'week_id query parameter is required' },
        { status: 400 }
      );
    }

    const gamePlan = getGamePlanByWeek(weekId);
    const plays = getPlaysByWeek(weekId);

    return NextResponse.json({
      game_plan: gamePlan || null,
      plays,
    });
  } catch (error: unknown) {
    console.error('Error fetching game plan:', error);
    const message = error instanceof Error ? error.message : 'Failed to fetch game plan';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { week_id, status, opening_script, call_sheet_data, tendency_notes, notes } = body;

    if (!week_id) {
      return NextResponse.json(
        { error: 'week_id is required' },
        { status: 400 }
      );
    }

    const id = body.id || uuidv4();

    upsertGamePlan({
      id,
      week_id,
      status: status || 'draft',
      opening_script: opening_script
        ? (typeof opening_script === 'string' ? opening_script : JSON.stringify(opening_script))
        : undefined,
      call_sheet_data: call_sheet_data
        ? (typeof call_sheet_data === 'string' ? call_sheet_data : JSON.stringify(call_sheet_data))
        : undefined,
      tendency_notes: tendency_notes || undefined,
      notes: notes || undefined,
    });

    return NextResponse.json({ id, week_id }, { status: 201 });
  } catch (error: unknown) {
    console.error('Error saving game plan:', error);
    const message = error instanceof Error ? error.message : 'Failed to save game plan';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

export async function PUT(request: NextRequest) {
  try {
    const body = await request.json();
    const { id, ...updates } = body;

    if (!id) {
      return NextResponse.json(
        { error: 'Game plan id is required in the request body' },
        { status: 400 }
      );
    }

    // Serialize JSON fields if they are objects
    const serialized: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(updates)) {
      if ((key === 'opening_script' || key === 'call_sheet_data') && typeof value === 'object') {
        serialized[key] = JSON.stringify(value);
      } else {
        serialized[key] = value;
      }
    }

    updateGamePlan(id, serialized);

    return NextResponse.json({ success: true });
  } catch (error: unknown) {
    console.error('Error updating game plan:', error);
    const message = error instanceof Error ? error.message : 'Failed to update game plan';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

