export function buildAnalysisPrompt(terminologyContext: string): string {
  let prompt = COACH_SYSTEM_PROMPT;
  if (terminologyContext) {
    prompt += `\n\n${terminologyContext}`;
  }
  prompt += `\n\n${ANALYSIS_PROMPT}`;
  return prompt;
}

export function buildChatSystemPrompt(
  terminologyContext: string,
  analysisContext: string
): string {
  let prompt = COACH_SYSTEM_PROMPT;
  if (terminologyContext) {
    prompt += `\n\n${terminologyContext}`;
  }
