import { NextRequest, NextResponse } from 'next/server';
import { v4 as uuidv4 } from 'uuid';
import { GoogleGenAI } from '@google/genai';
import {
  getTendencyReport,
  getAllPlays,
  getGamePlanByWeek,
  upsertGamePlan,
  insertPlay,
  updateGamePlan,
  getTerminologyAsContext,
} from '@/lib/db';
import { buildGamePlanPrompt } from '@/lib/prompts';

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY || '' });

interface GeneratedPlay {
  play_name: string;
  formation: string;
  play_type: string;
  personnel: string;
  full_call: string;
  why_it_works: string;
  confidence: number;
}

interface GeneratedGamePlan {
  first_and_ten: GeneratedPlay[];
  second_short: GeneratedPlay[];
  second_medium: GeneratedPlay[];
  second_long: GeneratedPlay[];
  third_short: GeneratedPlay[];
  third_medium: GeneratedPlay[];
  third_long: GeneratedPlay[];
  red_zone: GeneratedPlay[];
  goal_line: GeneratedPlay[];
  backed_up: GeneratedPlay[];
  two_minute: GeneratedPlay[];
  blitz_beaters: GeneratedPlay[];
  gadgets: GeneratedPlay[];
  two_point: GeneratedPlay[];
}

// Map section keys to situation tags for plays
const SECTION_TAG_MAP: Record<string, string[]> = {
  first_and_ten: ['1st & 10'],
  second_short: ['2nd & Short'],
  second_medium: ['2nd & Medium'],
  second_long: ['2nd & Long'],
  third_short: ['3rd & Short'],
  third_medium: ['3rd & Medium'],
  third_long: ['3rd & Long'],
  red_zone: ['Red Zone'],
  goal_line: ['Goal Line'],
  backed_up: ['Backed Up'],
  two_minute: ['Two-Minute'],
  blitz_beaters: ['Blitz Beater'],
  gadgets: ['Gadget/Trick'],
  two_point: ['2-Point Conversion'],
};

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { week_id, opponent_id } = body;

    if (!week_id || !opponent_id) {
      return NextResponse.json(
        { error: 'week_id and opponent_id are required' },
        { status: 400 }
      );
    }

    if (!process.env.GEMINI_API_KEY || process.env.GEMINI_API_KEY === 'your_key_here') {
      return NextResponse.json(
        { error: 'GEMINI_API_KEY not configured. Please add your API key to .env.local' },
        { status: 500 }
      );
    }

    // Get the tendency report for this opponent
    const tendencyReport = getTendencyReport(opponent_id);
    const tendencyData = tendencyReport
      ? tendencyReport.report_data
      : JSON.stringify({ overall_assessment: 'No tendency data available. Generate a general balanced game plan.' });

    // Get existing plays from the playbook
    const existingPlays = getAllPlays();
    const playsContext = existingPlays.length > 0
      ? JSON.stringify(
          existingPlays.map((p) => ({
            play_name: p.play_name,
            formation: p.formation,
            play_type: p.play_type,
            personnel: p.personnel,
            full_play_call: p.full_play_call,
          }))
        )
      : 'No existing plays in the playbook yet.';

    // Build prompt and call Gemini
    const terminologyContext = getTerminologyAsContext();
    const prompt = buildGamePlanPrompt(terminologyContext, tendencyData, playsContext);

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: { responseMimeType: 'application/json' },
    });

    const text = response.text || '';

    let parsed: GeneratedGamePlan;
    try {
      parsed = JSON.parse(text);
    } catch {
      const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
      if (jsonMatch) {
        parsed = JSON.parse(jsonMatch[1].trim());
      } else {
        parsed = JSON.parse(text.trim());
      }
    }

    // Save each generated play to the database with week_id, situation_tags, and personnel
    const savedPlayIds: string[] = [];

    for (const [section, plays] of Object.entries(parsed)) {
      if (!Array.isArray(plays)) continue;

      const situationTags = SECTION_TAG_MAP[section] || [section];

      for (const play of plays as GeneratedPlay[]) {
        const playId = uuidv4();
        insertPlay({
          id: playId,
          play_name: play.play_name || '',
          formation: play.formation || '',
          play_type: play.play_type || '',
          full_play_call: play.full_call || '',
          personnel: play.personnel || '11',
          situation_tags: JSON.stringify(situationTags),
          week_id,
          opponent_id,
          confidence_rank: play.confidence || 3,
          defensive_analysis: JSON.stringify({ why_it_works: play.why_it_works || '' }),
        });
        savedPlayIds.push(playId);
      }
    }

    // Ensure a game plan record exists and update it
    const existingPlan = getGamePlanByWeek(week_id);
    const gamePlanId = existingPlan?.id || uuidv4();

    if (!existingPlan) {
      upsertGamePlan({
        id: gamePlanId,
        week_id,
        status: 'in-progress',
        tendency_notes: tendencyData,
      });
    } else {
      updateGamePlan(gamePlanId, {
        status: 'in-progress',
        tendency_notes: tendencyData,
      });
    }

    return NextResponse.json({
      game_plan_id: gamePlanId,
      generated: parsed,
      saved_play_count: savedPlayIds.length,
    });
  } catch (error: unknown) {
    console.error('Game plan generation error:', error);
    const message = error instanceof Error ? error.message : 'Game plan generation failed';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

