export interface GamePlanRecord {
  id: string;
  week_id: string;
  status: string;
  opening_script: string;
  call_sheet_data: string;
  tendency_notes: string;
  notes: string;
  created_at: string;
  updated_at: string;
}

export function getGamePlanByWeek(weekId: string): GamePlanRecord | undefined {
  const database = getDb();
  return database.prepare('SELECT * FROM game_plans WHERE week_id = ?').get(weekId) as GamePlanRecord | undefined;
}

export function upsertGamePlan(plan: Partial<GamePlanRecord> & { id: string; week_id: string }): void {
  const database = getDb();
  database.prepare(
    `INSERT OR REPLACE INTO game_plans (id, week_id, status, opening_script, call_sheet_data, tendency_notes, notes, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'))`
  ).run(
    plan.id,
    plan.week_id,
    plan.status || 'draft',
    plan.opening_script || '[]',
    plan.call_sheet_data || '{}',
    plan.tendency_notes || '',
    plan.notes || ''
  );
}

export function updateGamePlan(id: string, updates: Partial<GamePlanRecord>): void {
  const database = getDb();
  const fields: string[] = ["updated_at = datetime('now')"];
  const values: unknown[] = [];
  for (const [key, value] of Object.entries(updates)) {
    if (key !== 'id' && key !== 'created_at' && key !== 'updated_at') {
      fields.push(`${key} = ?`);
      values.push(value);
    }
  }
  values.push(id);
  database.prepare(`UPDATE game_plans SET ${fields.join(', ')} WHERE id = ?`).run(...values);
}

