  film_count: number;
  created_at: string;
  updated_at: string;
}

export function getTendencyReport(opponentId: string): TendencyReportRecord | undefined {
  const database = getDb();
  return database.prepare('SELECT * FROM tendency_reports WHERE opponent_id = ? ORDER BY updated_at DESC LIMIT 1').get(opponentId) as TendencyReportRecord | undefined;
}

export function upsertTendencyReport(report: Partial<TendencyReportRecord> & { id: string; opponent_id: string }): void {
  const database = getDb();
  database.prepare(
    `INSERT OR REPLACE INTO tendency_reports (id, opponent_id, report_data, film_count, updated_at)
     VALUES (?, ?, ?, ?, datetime('now'))`
  ).run(
    report.id,
    report.opponent_id,
    report.report_data || '{}',
    report.film_count || 0
  );
}

