 62	export async function POST(request: NextRequest) {
 63	  try {
 64	    const body = await request.json();
 65	    const { week_id, opponent_id } = body;
 66	
 67	    if (!week_id || !opponent_id) {
 68	      return NextResponse.json(
 69	        { error: 'week_id and opponent_id are required' },
 70	        { status: 400 }
 71	      );
 72	    }
 73	
 74	    if (!process.env.GEMINI_API_KEY || process.env.GEMINI_API_KEY === 'your_key_here') {
 75	      return NextResponse.json(
 76	        { error: 'GEMINI_API_KEY not configured. Please add your API key to .env.local' },
 77	        { status: 500 }
 78	      );
 79	    }
 80	
 81	    // Get the tendency report for this opponent
 82	    const tendencyReport = getTendencyReport(opponent_id);
 83	    const tendencyData = tendencyReport
 84	      ? tendencyReport.report_data
 85	      : JSON.stringify({ overall_assessment: 'No tendency data available. Generate a general balanced game plan.' });
 86	
 87	    // Get existing plays from the playbook
 88	    const existingPlays = getAllPlays();
 89	    const playsContext = existingPlays.length > 0
 90	      ? JSON.stringify(
 91	          existingPlays.map((p) => ({
 92	            play_name: p.play_name,
 93	            formation: p.formation,
 94	            play_type: p.play_type,
 95	            personnel: p.personnel,
 96	            full_play_call: p.full_play_call,
 97	          }))
 98	        )
 99	      : 'No existing plays in the playbook yet.';
100	
101	    // Build prompt and call Gemini
102	    const terminologyContext = getTerminologyAsContext();
103	    const prompt = buildGamePlanPrompt(terminologyContext, tendencyData, playsContext);
104	
105	    const response = await ai.models.generateContent({
106	      model: 'gemini-3-pro-preview',
107	      contents: [{ role: 'user', parts: [{ text: prompt }] }],
108	      config: { responseMimeType: 'application/json' },
109	    });
110	
111	    const text = response.text || '';
112	
113	    let parsed: GeneratedGamePlan;
114	    try {
115	      parsed = JSON.parse(text);
116	    } catch {
117	      const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
118	      if (jsonMatch) {
119	        parsed = JSON.parse(jsonMatch[1].trim());
120	      } else {
121	        parsed = JSON.parse(text.trim());
122	      }
123	    }
124	
125	    // Save each generated play to the database with week_id, situation_tags, and personnel
126	    const savedPlayIds: string[] = [];
127	
128	    for (const [section, plays] of Object.entries(parsed)) {
129	      if (!Array.isArray(plays)) continue;
130	
131	      const situationTags = SECTION_TAG_MAP[section] || [section];
132	
133	      for (const play of plays as GeneratedPlay[]) {
134	        const playId = uuidv4();
135	        insertPlay({
136	          id: playId,
137	          play_name: play.play_name || '',
138	          formation: play.formation || '',
139	          play_type: play.play_type || '',
140	          full_play_call: play.full_call || '',
141	          personnel: play.personnel || '11',
142	          situation_tags: JSON.stringify(situationTags),
143	          week_id,
144	          opponent_id,
145	          confidence_rank: play.confidence || 3,
146	          defensive_analysis: JSON.stringify({ why_it_works: play.why_it_works || '' }),
147	        });
148	        savedPlayIds.push(playId);
149	      }
150	    }
151	
152	    // Ensure a game plan record exists and update it
153	    const existingPlan = getGamePlanByWeek(week_id);
154	    const gamePlanId = existingPlan?.id || uuidv4();
155	
156	    if (!existingPlan) {
157	      upsertGamePlan({
158	        id: gamePlanId,
159	        week_id,
160	        status: 'in-progress',
161	        tendency_notes: tendencyData,
162	      });
163	    } else {
164	      updateGamePlan(gamePlanId, {
165	        status: 'in-progress',
166	        tendency_notes: tendencyData,
167	      });
168	    }
169	
170	    return NextResponse.json({
171	      game_plan_id: gamePlanId,
172	      generated: parsed,
173	      saved_play_count: savedPlayIds.length,
174	    });
175	  } catch (error: unknown) {
176	    console.error('Game plan generation error:', error);
177	    const message = error instanceof Error ? error.message : 'Game plan generation failed';
