 52	export async function POST(request: NextRequest) {
 53	  try {
 54	    const body = await request.json();
 55	    const { opponent_id, files } = body;
 56	
 57	    if (!opponent_id) {
 58	      return NextResponse.json(
 59	        { error: 'opponent_id is required' },
 60	        { status: 400 }
 61	      );
 62	    }
 63	
 64	    if (!files || !Array.isArray(files) || files.length === 0) {
 65	      return NextResponse.json(
 66	        { error: 'files array is required with at least one media file' },
 67	        { status: 400 }
 68	      );
 69	    }
 70	
 71	    if (!process.env.GEMINI_API_KEY || process.env.GEMINI_API_KEY === 'your_key_here') {
 72	      return NextResponse.json(
 73	        { error: 'GEMINI_API_KEY not configured. Please add your API key to .env.local' },
 74	        { status: 500 }
 75	      );
 76	    }
 77	
 78	    // Build the prompt
 79	    const terminologyContext = getTerminologyAsContext();
 80	    const prompt = buildTendencyPrompt(terminologyContext);
 81	
 82	    // Build parts: all media files + text prompt
 83	    const parts: Array<{ inlineData: { mimeType: string; data: string } } | { text: string }> = [];
 84	
 85	    for (const file of files) {
 86	      if (file.media && file.mimeType) {
 87	        parts.push({
 88	          inlineData: { mimeType: file.mimeType, data: file.media },
 89	        });
 90	      }
 91	    }
 92	
 93	    if (parts.length === 0) {
 94	      return NextResponse.json(
 95	        { error: 'No valid media files found in the request' },
 96	        { status: 400 }
 97	      );
 98	    }
 99	
100	    parts.push({ text: prompt });
101	
102	    // Call Gemini to analyze the film
103	    const response = await ai.models.generateContent({
104	      model: 'gemini-3-pro-preview',
105	      contents: [{ role: 'user', parts }],
106	      config: { responseMimeType: 'application/json' },
107	    });
108	
109	    const text = response.text || '';
110	
111	    let parsed;
112	    try {
113	      parsed = JSON.parse(text);
114	    } catch {
115	      const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
116	      if (jsonMatch) {
117	        parsed = JSON.parse(jsonMatch[1].trim());
118	      } else {
119	        parsed = JSON.parse(text.trim());
120	      }
121	    }
122	
123	    // Check if there is an existing report to update (increment film count)
124	    const existingReport = getTendencyReport(opponent_id);
125	    const reportId = existingReport?.id || uuidv4();
126	    const filmCount = (existingReport?.film_count || 0) + files.length;
127	
128	    // Save or update the tendency report
129	    upsertTendencyReport({
130	      id: reportId,
131	      opponent_id,
132	      report_data: JSON.stringify(parsed),
133	      film_count: filmCount,
134	    });
135	
136	    return NextResponse.json({
137	      id: reportId,
138	      opponent_id,
139	      report_data: parsed,
140	      film_count: filmCount,
141	    });
142	  } catch (error: unknown) {
143	    console.error('Tendency analysis error:', error);
144	    const message = error instanceof Error ? error.message : 'Tendency analysis failed';
145	    return NextResponse.json({ error: message }, { status: 500 });
146	  }
147	}

