492	export function getTerminologyAsContext(): string {
493	  const terms = getAllTerminology();
494	  if (terms.length === 0) return '';
495	
496	  const grouped: Record<string, { standard: string; custom: string }[]> = {};
497	  for (const t of terms) {
498	    if (!grouped[t.category]) grouped[t.category] = [];
499	    grouped[t.category].push({
500	      standard: t.standard_term,
501	      custom: t.custom_term,
502	    });
503	  }
504	
505	  let context = 'CUSTOM TERMINOLOGY — Use these terms exclusively:\n';
506	  for (const [category, mappings] of Object.entries(grouped)) {
507	    context += `\n[${category.toUpperCase()}]\n`;
508	    for (const m of mappings) {
509	      context += `  "${m.standard}" → use "${m.custom}" instead\n`;
510	    }
511	  }
512	  return context;
513	}
